// RAID items and the stakeholder email come straight from the specialists,
// so the orchestrator's review cannot silently change what the PM approves.
const review = $('Orchestrator: Review').first().json.output;
const raid = $('RAID Specialist').first().json.output || {};
const comms = $('Comms Specialist').first().json.output || {};
return [{ json: { output: {
  headline: review.headline,
  status: review.status || { executiveSummary: '', doneThisWeek: [], nextWeek: [] },
  schedule: review.schedule || { findings: [], recommendation: '' },
  decisionsNeeded: review.decisionsNeeded || [],
  reviewNotes: review.reviewNotes || '',
  newRaidItems: raid.newRaidItems || [],
  updatesToExisting: raid.updatesToExisting || [],
  stakeholderUpdate: { subject: comms.subject || '', body: comms.body || '' }
} } }];

// Email layout helpers: full width, left aligned, table-based so Outlook renders it consistently.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const F = 'font-family:Segoe UI,Arial,Helvetica,sans-serif;color:#1f2937;';
const T = (t, sub) => '<p style="' + F + 'margin:0 0 4px 0;font-size:20px;font-weight:700;line-height:1.3">' + t + '</p>' + (sub ? '<p style="' + F + 'margin:0 0 14px 0;font-size:13px;color:#6b7280">' + sub + '</p>' : '');
const H = (t) => '<p style="' + F + 'margin:20px 0 8px 0;font-size:15px;font-weight:700">' + t + '</p>';
const P = (t) => '<p style="' + F + 'margin:0 0 10px 0;font-size:14px;line-height:1.5">' + t + '</p>';
const UL = (a) => (a && a.length) ? '<ul style="' + F + 'margin:0 0 10px 0;padding:0 0 0 20px;font-size:14px;line-height:1.5">' + a.map(x => '<li style="margin:0 0 4px 0">' + esc(x) + '</li>').join('') + '</ul>' : P('<em>None</em>');
const CELL = F + 'border:1px solid #d1d5db;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px;line-height:1.4;';
const TBL = (head, rows) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 10px 0">' + (head ? '<tr>' + head.map(h => '<th style="' + CELL + 'background:#f3f4f6;font-weight:700">' + h + '</th>').join('') + '</tr>' : '') + rows.map(r => '<tr>' + r.map(c => '<td style="' + CELL + '">' + c + '</td>').join('') + '</tr>').join('') + '</table>';
const BOX = (t, line, bg) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 12px 0"><tr><td style="' + F + 'background:' + bg + ';border-left:4px solid ' + line + ';padding:10px 12px;font-size:14px;line-height:1.5">' + t + '</td></tr></table>';
const PILL = (t, bg) => '<span style="background:' + bg + ';color:#ffffff;padding:2px 10px;border-radius:10px;font-weight:700;font-size:12px">' + t + '</span>';
const BTN = '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:16px 0"><tr><td style="background:#1f4e79;border-radius:4px"><a href="%%DECIDE_URL%%" style="' + F + 'display:inline-block;padding:11px 22px;color:#ffffff;font-size:14px;font-weight:700;text-decoration:none">Review and decide</a></td></tr></table>';
const NOTE = (t) => '<p style="' + F + 'margin:16px 0 0 0;font-size:12px;line-height:1.5;color:#6b7280">' + t + '</p>';
const WRAP = (inner) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse"><tr><td style="' + F + 'padding:0;text-align:left">' + inner + '</td></tr></table>';
const RAG = { Green: '#1e7e34', Amber: '#b26a00', Red: '#b00020' };
const p = $input.first().json.output;
const c = $('Build Context Pack').first().json;
const raidRows = (p.newRaidItems || []).map(r => [esc(r.raid_type), esc(r.title), esc(r.impact), esc(r.likelihood), esc(r.owner), esc(r.mitigation)]);
const body = T(esc(p.headline), esc(c.project.name) + ' · weekly review · ' + esc(c.reportDate))
  + BOX(PILL(c.health.rag.toUpperCase(), RAG[c.health.rag]) + '&nbsp;&nbsp;' + c.health.percentComplete + '% complete · ' + c.health.budgetUsedPct + '% of budget used<br><span style="font-size:13px;color:#4b5563">Why (rules): ' + c.health.ragReasons.map(esc).join('; ') + '</span>', RAG[c.health.rag], '#f9fafb')
  + BTN
  + H('1. Status') + P(esc(p.status.executiveSummary)) + P('<b>Done</b>') + UL(p.status.doneThisWeek) + P('<b>Next week</b>') + UL(p.status.nextWeek)
  + H('2. Schedule') + UL(p.schedule.findings) + P('<b>Recommendation:</b> ' + esc(p.schedule.recommendation))
  + H('3. New RAID items (added to the RAID log if you approve)') + (raidRows.length ? TBL(['Type', 'Title', 'Impact', 'Likelihood', 'Owner', 'Mitigation'], raidRows) : P('<em>No new items</em>'))
  + H('4. Stakeholder update (saved as an Outlook draft if you approve)') + BOX('<b>' + esc(p.stakeholderUpdate.subject) + '</b><br>' + esc(p.stakeholderUpdate.body).replace(/\n/g, '<br>'), '#9ca3af', '#f9fafb')
  + H('Suggested changes to existing RAID entries (not applied automatically)') + UL(p.updatesToExisting)
  + H('Decisions needed') + UL(p.decisionsNeeded)
  + (p.reviewNotes ? P('<b>Orchestrator review notes:</b> ' + esc(p.reviewNotes)) : '')
  + BTN
  + NOTE('Nothing has been written to any system yet. Approve to add the RAID items and save the update as a draft. Reject to discard. Your decision and comment are saved in the audit log.');
return [{ json: { subject: '[Approval needed] ' + p.headline, html: WRAP(body) } }];
